"""Measured extensions motivated by the project's earlier planning transcript."""
import csv


def read(path):
    with path.open(newline='',encoding='utf-8') as f:
        return list(csv.DictReader(f))


def load(results):
    return {'main':read(results/'soft_labels/metrics.csv'),
            'repeat':read(results/'soft_labels/repeat/metrics.csv'),
            'binary':read(results/'binary_information/summary.csv'),
            'binary_repeat':read(results/'binary_information/repeat/summary.csv'),
            'optimizer':read(results/'optimizer_control/metrics.csv'),
            'optimizer_repeat':read(results/'optimizer_control/repeat/metrics.csv')}


def soft(data,k,r,rho,budget=4608,repeated=False):
    return next(v for v in data['extensions']['repeat' if repeated else 'main']
                if int(v['chains'])==k and int(v['reads'])==r and float(v['correlation'])==rho and int(v['budget'])==budget)


def effect(row,name='gain_over_majority'):
    from build import pct
    return f"{pct(row[name])} [{pct(row[name+'_low'])}; {pct(row[name+'_high'])}]"


def add_word(doc,results,data):
    from build import SECTIONS,new_page,table,figure,pct
    p=doc.add_paragraph
    new_page(doc,SECTIONS[17].upper())
    p('Дополнение из первоначального плана проверяет, что теряется при замене повторных ответов одним голосом большинства. Для тех же устройств и физических чтений раздела 12 сравниваются большинство и q = число ответов «1» / r. Сохранены одинаковые начальные веса, два старта, лимит 180 итераций и выбор по общей валидации. Новых обращений к PUF мягкая метка не требует.')
    p('При оценке P(Y = 1) = sigmoid(−s), где s — произведение оценок задержек, BCE равна log(1 + exp(s)) − (1 − q)s. Она точно совпадает со средней BCE всех r исходных битов. Это равенство потерь верно и для зависимых чтений; интерпретация через независимое правдоподобие при корреляции уже не применима. Градиент и равенство проверены отдельно.')
    p('Таблица 10 — Доли ответов минус большинство, п. п.; B = 4608, σ = 0,25. Парные 95%-е интервалы по пяти устройствам в каждой серии.')
    table(doc,('k','r','ρ','Доли − большинство, п. п.','Повтор, п. п.'),[
        (k,r,str(rho).replace('.',','),effect(soft(data,k,r,rho)),effect(soft(data,k,r,rho,repeated=True)))
        for k in (1,2) for r in (3,9) for rho in (0.,.9)
    ],widths=(.8,.8,1.2,6.8,6.8))
    figure(doc,results/'soft_labels/soft_vs_majority.png','Рисунок 7 — Парный эффект мягких меток при обоих бюджетах.')
    a=soft(data,2,9,0.);b=soft(data,2,9,0.,repeated=True)
    p(f"Для 2-XOR, r = 9, ρ = 0 точность выросла с {pct(a['majority_accuracy'])}% до {pct(a['accuracy'])}%; повтор — с {pct(b['majority_accuracy'])}% до {pct(b['accuracy'])}%. Относительно разных запросов эффект составил {effect(a,'gain_over_single')} п. п. и {effect(b,'gain_over_single')} п. п. Улучшение над большинством не означает превосходства над новыми CRP.")
    p('Ожидаемая точность нового шумного чтения также сохранена; задержки доступны только оценщику. Вывод ограничен пятью устройствами на серию и выбранной невыпуклой моделью; интервалы точечные. Контроль оптимизации приведён в разделе 19.')

    new_page(doc,SECTIONS[18].upper())
    p('Для одной цепочки с известным σ > 0 и независимым шумом положим x = φ(c), t = wᵀx/σ, p = Φ(−t), где Φ — функция распределения стандартной нормали, g — её плотность. Информация одного бинарного ответа о w равна I(c) = g(t)²xxᵀ / {σ²p(1 − p)}. Она получается из score = −(Y − p)g(t)x / {σp(1 − p)} и Var(Y) = p(1 − p). Это информация бита, а не аналоговая верхняя граница раздела 16.')
    p('При T обращениях и r независимых чтениях каждого из m = T/r случайных запросов условная информация полных ответов Jᵣ = rΣⱼI(cⱼ). Для независимых равномерных запросов с возвращением: E[Jᵣ] = T E[I(c)], Cov(vec Jᵣ) = rT Cov(vec I(c)). Среднее сохраняется, а дисперсия по случайным планам возрастает в r раз. Кроме того, rank(Jᵣ) ≤ min(m, 65). Это ограничение локальной идентификации весов, не доказательство ошибки любого классификатора.')
    p('Расчёт оценщика проверяет J₀₀ на 4000 планах для каждого r и каждого из двух фиксированных PUF: всего 24000 планов, T = 576, σ = 0,75. Число чтений — 1, 3 и 9. Подвыборки для разных r парные; между планами запросы независимы. Таблица 11 показывает отношение дисперсий к r = 1 с бутстрэп-интервалом.')
    def ratio(row):
        return f"{float(row['variance_ratio']):.2f} [{float(row['variance_ratio_low']):.2f}; {float(row['variance_ratio_high']):.2f}]".replace('.',',')
    table(doc,('r','Основная серия','Другой PUF','Теория'),[
        (a['reads'],ratio(a),ratio(b),a['predicted_variance_ratio'])
        for a,b in zip(data['extensions']['binary'],data['extensions']['binary_repeat'])
    ],widths=(1,6,6,3))
    figure(doc,results/'binary_information/binary_information.png','Рисунок 8 — Средняя информация и разброс случайных планов запросов.')
    p('Число единиц — достаточная статистика независимых Bernoulli-повторов; большинство в общем случае теряет информацию. Например, при p = 1/2 три чтения после большинства сохраняют 75% информации полных битов. Это проверено суммированием биномиального распределения. В атаках запросы выбираются без повторений, здесь — с возвращением для точного тождества; перенос на коррелированный шум не делается. Формулы не доказывают превосходство мягких меток по конечной accuracy.')


    new_page(doc,SECTIONS[19].upper())
    p('Во время итоговой проверки выявлено ограничение сильного эффекта раздела 17: при 2-XOR, B = 4608, r = 9 и независимом шуме все пять выбранных моделей большинства достигли лимита 180 итераций без флага сходимости. Поэтому после основной серии проведён дополнительный контроль оптимизации и регуляризации на тех же десяти устройствах. Это исследовательская проверка чувствительности, а не заранее зарегистрированный подтверждающий опыт.')
    p('Сохраняются запросы, шум, физический бюджет и 512 валидационных ответов. Сравниваются четыре настройки: исходная; 1000 итераций при двух стартах; восемь стартов по 1000 итераций; тот же вычислительный лимит с L2-коэффициентом 0,01 вместо 0,0001. Для обоих способов разметки совпадают начальные веса и правила выбора старта. Тестовые метки не участвуют в выборе модели.')
    p('Таблица 12 — Контроль большого эффекта мягких меток. Первые два столбца точности относятся к основной серии; разности и точечные 95%-е интервалы — парные по устройствам. Формат настройки: старты × максимум итераций; коэффициент L2.')
    settings=('2 × 180; 0,0001','2 × 1000; 0,0001','8 × 1000; 0,0001','8 × 1000; 0,01')
    def delta(row):
        return f"{pct(row['paired_gain'])} [{pct(row['ci_low'])}; {pct(row['ci_high'])}]"
    table(doc,('Настройка','Большинство, %','Доли, %','Разность, п. п.','Повтор, п. п.'),[
        (name,pct(a['majority_accuracy']),pct(a['fraction_accuracy']),delta(a),delta(b))
        for name,a,b in zip(settings,data['extensions']['optimizer'],data['extensions']['optimizer_repeat'])
    ],widths=(2.8,3.0,2.0,4.3,4.3))
    a=data['extensions']['optimizer'][-1];b=data['extensions']['optimizer_repeat'][-1]
    p(f"Сильнейший из проверенных контролей уменьшил преимущество до {delta(a)} п. п.; в повторе — {delta(b)} п. п. Все выбранные модели в этой настройке получили флаг сходимости. Одно увеличение числа итераций не устранило разрыв; дополнительные старты и регуляризация заметно усилили модель с большинством.")
    p('Следовательно, исходные 21,50 и 19,96 п. п. характеризуют конкретную настройку обучения. Их нельзя целиком объяснять информационными потерями большинства или переносить на любые классификаторы. Положительный остаточный эффект сохраняется в проверенном контроле, однако полного поиска архитектур, регуляризации и оптимизаторов не выполнялось. Сходимость численного метода не гарантирует глобальный минимум.')
    p('Базовые предсказания контроля совпали с первоначальными по каждому тестовому биту. Веса, все попытки и итоговые прогнозы сохранены; аудитор заново проверяет функцию потерь, норму градиента, выбор по валидации и бюджет. Поток бутстрэпа в контроле отдельный, поэтому границы базового интервала могут немного отличаться от раздела 17.')


def add_slides(deck,results,data):
    from build import page,text,tiles,pct,INK,TEAL,MUTED
    from pptx.util import Inches
    a=soft(data,2,9,0.);b=soft(data,2,9,0.,repeated=True)
    slide=page(deck,'Дополнение из плана','Сохранять доли ответов вместо большинства')
    tiles(slide,[(f"{pct(a['majority_accuracy'])}% → {pct(a['accuracy'])}%",'2-XOR, B = 4608, r = 9, ρ = 0'),
                 (f"+{pct(b['gain_over_majority'])} п. п.",'Выигрыш на пяти новых устройствах')])
    text(slide,'Те же измеренные биты, начальные веса и валидация. Меняется обучающая метка.',.65,4.35,12,.9,22,INK,True)
    text(slide,'Выигрыш над большинством подтвердился. Превосходство над разными запросами не установлено.',.65,5.6,12,1.,21,TEAL,True)
    slide=page(deck,'Математическое дополнение','Информация бинарных ответов при равном бюджете')
    slide.shapes.add_picture(str(results/'binary_information/binary_information.png'), Inches(.8), Inches(1.8), width=Inches(11.7))
    text(slide,'Независимый шум: среднее сохраняется, разброс дизайна растёт в r раз. 24000 планов.',.65,6.3,12,.8,19,TEAL,True)
    slide=page(deck,'Проверка устойчивости','Размер эффекта зависит от настройки обучения')
    a=data['extensions']['optimizer'][-1];b=data['extensions']['optimizer_repeat'][-1]
    tiles(slide,[(f"+{pct(a['paired_gain'])} п. п.",'После 8 стартов, 1000 итераций и L2 = 0,01'),
                 (f"+{pct(b['paired_gain'])} п. п.",'Независимый повтор; оба интервала положительны')])
    text(slide,'Исходный выигрыш 21,50 / 19,96 п. п. уменьшился после усиления модели большинства.',.65,4.35,12,1.,22,INK,True)
    text(slide,'Это проверка чувствительности после основной серии. Универсальный размер выигрыша не установлен.',.65,5.7,12,1.,20,TEAL,True)
